CREATE TABLE permit_phase_config (\n  jurisdiction varchar(40) NOT NULL,\n  permit_type  varchar(60) NOT NULL,\n  phase        varchar(30) NOT NULL,\n  time_unit    varchar(15) NOT NULL CHECK (time_unit IN ('CALENDAR_DAYS','BUSINESS_DAYS')),\n  duration     int NOT NULL CHECK (duration > 0),\n  PRIMARY KEY (jurisdiction, permit_type, phase)\n);\nINSERT INTO permit_phase_config VALUES\n  ('MX_CDMX','CONSTRUCCION_NUEVA','REVIEW','BUSINESS_DAYS',30),\n  ('MX_CDMX','CONSTRUCCION_NUEVA','OBSERVED','BUSINESS_DAYS',15),\n  ('ES_MADRID','LICENCIA_OBRA','REVIEW','CALENDAR_DAYS',60),\n  ('US_TX','BUILDING_PERMIT','REVIEW','CALENDAR_DAYS',45);\n\nCREATE TYPE observation_state AS ENUM ('NOT_STARTED','IN_PROGRESS','COMPLETE');\nCREATE TYPE observation_validity AS ENUM (\n  'VALID','INVALID_OCCLUSION','INVALID_MODEL_DEGRADED',\n  'INVALID_MANUAL_CORRECTION','PENDING_REVIEW'\n);\nCREATE TYPE progress_status AS ENUM ('DRAFT','READY_FOR_REVIEW','CERTIFIED','REJECTED');\n\nCREATE TABLE bim_element_observation (\n  tenant_id             uuid NOT NULL,\n  observation_id        uuid NOT NULL,\n  project_id            uuid NOT NULL,\n  work_package_id       uuid NOT NULL,\n  ifc_guid              varchar(80) NOT NULL,\n  ifc_class             varchar(80) NOT NULL,\n  observed_state        observation_state NOT NULL,\n  observed_quantity     numeric(18,4) NOT NULL CHECK (observed_quantity >= 0),\n  planned_quantity      numeric(18,4) NOT NULL CHECK (planned_quantity > 0),\n  visibility_ratio      numeric(6,4) NOT NULL CHECK (visibility_ratio BETWEEN 0 AND 1),\n  confidence_calibrated numeric(6,4) NOT NULL CHECK (confidence_calibrated BETWEEN 0 AND 1),\n  reprojection_error    numeric(10,4) NOT NULL,\n  coverage              numeric(6,4) NOT NULL CHECK (coverage BETWEEN 0 AND 1),\n  evidence_refs         jsonb NOT NULL,\n  model_id              varchar(80) NOT NULL,\n  model_version         varchar(40) NOT NULL,\n  training_dataset_hash varchar(64) NOT NULL,\n  calibration_params    jsonb NOT NULL,\n  observed_at           timestamptz NOT NULL,\n  recorded_by           uuid NOT NULL,\n  validity              observation_validity NOT NULL DEFAULT 'VALID',\n  invalidation_reason   text,\n  aggregate_version     bigint NOT NULL DEFAULT 1,\n  created_at            timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, observation_id),\n  CHECK (jsonb_array_length(evidence_refs) > 0),\n  CHECK (validity = 'VALID' OR invalidation_reason IS NOT NULL),\n  CHECK (observed_state <> 'COMPLETE' OR visibility_ratio >= 0.7)\n);\n\nCREATE TABLE progress_observation (\n  tenant_id               uuid NOT NULL,\n  progress_observation_id uuid NOT NULL,\n  project_id              uuid NOT NULL,\n  work_package_id         uuid NOT NULL,\n  period_start            date NOT NULL,\n  period_end              date NOT NULL,\n  observation_refs        jsonb NOT NULL,\n  progress_ratio_point    numeric(6,4) NOT NULL,\n  progress_ratio_lower    numeric(6,4) NOT NULL,\n  progress_ratio_upper    numeric(6,4) NOT NULL,\n  confidence_level        numeric(4,3) NOT NULL CHECK (confidence_level > 0 AND confidence_level <= 1),\n  status                  progress_status NOT NULL DEFAULT 'DRAFT',\n  certified_at            timestamptz,\n  certified_by            uuid,\n  rejection_reason        text,\n  evidence_manifest_id    uuid,\n  model_versions_used     jsonb NOT NULL,\n  contractual_threshold   numeric(6,4) NOT NULL,\n  aggregate_version       bigint NOT NULL DEFAULT 1,\n  PRIMARY KEY (tenant_id, progress_observation_id),\n  CHECK (progress_ratio_lower <= progress_ratio_point),\n  CHECK (progress_ratio_point <= progress_ratio_upper),\n  CHECK (progress_ratio_lower >= 0 AND progress_ratio_upper <= 1),\n  CHECK (period_start <= period_end),\n  CHECK (status <> 'CERTIFIED' OR progress_ratio_lower >= contractual_threshold)\n);\n\nCREATE TABLE progress_certified_read_model (\n  tenant_id               uuid NOT NULL,\n  progress_observation_id uuid NOT NULL,\n  project_id              uuid NOT NULL,\n  work_package_id         uuid NOT NULL,\n  period_start            date NOT NULL,\n  period_end              date NOT NULL,\n  progress_ratio_point    numeric(6,4) NOT NULL,\n  progress_ratio_lower    numeric(6,4) NOT NULL,\n  progress_ratio_upper    numeric(6,4) NOT NULL,\n  certified_at            timestamptz NOT NULL,\n  certified_by            uuid NOT NULL,\n  evidence_manifest_id    uuid NOT NULL,\n  PRIMARY KEY (tenant_id, progress_observation_id)\n);\n\n-- permit_phase_config es configuración global (sin tenant_id): sin RLS por tenant\nALTER TABLE bim_element_observation    ENABLE ROW LEVEL SECURITY;\nALTER TABLE progress_observation       ENABLE ROW LEVEL SECURITY;\nALTER TABLE progress_certified_read_model ENABLE ROW LEVEL SECURITY;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'bim_element_observation','progress_observation',\n    'progress_certified_read_model'\n  ]) LOOP\n    EXECUTE format('CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)', t, t);\n  END LOOP;\nEND $$;